const tabActions = new Map();

const invalidateTabActions = (tabId, retired = false) => {
    const entry = tabActions.get(tabId);
    if ( entry === undefined ) { return; }
    entry.epoch += 1;
    entry.retired = retired;
    for ( const action of entry.actions.values() ) {
        action.value = undefined;
    }
    // Keep outstanding writes visible to a new document or reused tab id.
    if ( retired && entry.pending === 0 ) { tabActions.delete(tabId); }
};

browser.webNavigation.onCommitted.addListener(details => {
    if ( details.frameId === 0 ) { invalidateTabActions(details.tabId); }
});
browser.webNavigation.onErrorOccurred.addListener(details => {
    if ( details.frameId === 0 ) { invalidateTabActions(details.tabId); }
});
browser.tabs.onUpdated.addListener((tabId, changeInfo) => {
    if ( changeInfo.status !== undefined || changeInfo.url !== undefined ) {
        invalidateTabActions(tabId);
    }
});
browser.tabs.onRemoved.addListener(tabId => {
    invalidateTabActions(tabId, true);
});
browser.tabs.onReplaced.addListener((addedTabId, removedTabId) => {
    invalidateTabActions(removedTabId, true);
    invalidateTabActions(addedTabId, true);
});
browser.tabs.onCreated.addListener(tab => {
    invalidateTabActions(tab.id, true);
});

const setTabAction = (method, details, value) => {
    const { tabId } = details;
    let entry = tabActions.get(tabId);
    if ( entry === undefined ) {
        entry = { epoch: 0, retired: false, pending: 0, actions: new Map() };
        tabActions.set(tabId, entry);
    }
    entry.retired = false;
    let action = entry.actions.get(method);
    if ( action === undefined ) {
        action = { pending: 0, overlap: false, value: undefined };
        entry.actions.set(method, action);
    }
    if ( value !== undefined && action.pending === 0 && action.value === value ) {
        return;
    }
    if ( action.pending !== 0 ) { action.overlap = true; }
    action.value = undefined;
    action.pending += 1;
    entry.pending += 1;
    const epoch = entry.epoch;
    browserAction[method](details).then(succeeded => {
        action.pending -= 1;
        entry.pending -= 1;
        // Callback order need not be the order in which native writes apply.
        if ( action.pending === 0 ) {
            if ( succeeded === true && action.overlap === false &&
                entry.epoch === epoch ) {
                action.value = value;
            }
            action.overlap = false;
        }
        if ( entry.retired && entry.pending === 0 ) {
            tabActions.delete(tabId);
        }
    });
};

