const promisifyAction = function(thisArg, fnName) {
    const fn = thisArg[fnName];
    return function(...args) {
        return new Promise(resolve => {
            try {
                fn.call(thisArg, ...args, function() {
                    resolve(chrome.runtime.lastError === undefined);
                });
            } catch(ex) {
                console.error(ex);
                resolve(false);
            }
        });
    };
